params.command:
$ErrorActionPreference='Stop'
$repo = Join-Path $env:USERPROFILE 'local-ai-workspaces\mhw-mods'
$runner = Join-Path $env:USERPROFILE 'actions-runner-heaven'
$listener = Join-Path $runner 'bin\Runner.Listener.exe'
$proc = Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Runner.Listener.exe' -and $_.ExecutablePath -like "$runner*" } | Select-Object -First 1 ProcessId,ExecutablePath,CommandLine
$task = Get-ScheduledTask -TaskName 'GitHub Actions Runner - heaven' -ErrorAction SilentlyContinue
[ordered]@{
  repo_exists = Test-Path $repo
  repo_head = if (Test-Path (Join-Path $repo '.git')) { (git -C $repo rev-parse HEAD 2>$null) } else { $null }
  repo_branch = if (Test-Path (Join-Path $repo '.git')) { (git -C $repo branch --show-current 2>$null) } else { $null }
  runner_dir_exists = Test-Path $runner
  configured = Test-Path (Join-Path $runner '.runner')
  listener_exists = Test-Path $listener
  runner_version = if (Test-Path $listener) { (Get-Item $listener).VersionInfo.ProductVersion } else { $null }
  listener_process = $proc
  scheduled_task_state = if ($task) { [string]$task.State } else { $null }
  scheduled_task_runlevel = if ($task) { [string]$task.Principal.RunLevel } else { $null }
} | ConvertTo-Json -Depth 5
